export function CommandPaletteDemo({
  open: openProp,
  onOpenChange,
  defaultOpen = false,
  showcase = true,
  controlled = false,
  empty = false,
  longContent = false,
  simulateSyncFailure = false,
}: {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  defaultOpen?: boolean;
  showcase?: boolean;
  controlled?: boolean;
  empty?: boolean;
  longContent?: boolean;
  simulateSyncFailure?: boolean;
}) {
  const [open, setOpen] = useState(defaultOpen);
  const [selected, setSelected] = useState(
    "Find a project, open a document, or run an action.",
  );
  const attempts = useRef(0);
  const [helpOpen, setHelpOpen] = useState(false);
  const initialScopes = ["Projects", "Documents", "Actions"];
  const [scopes, setScopes] = useState(initialScopes);
  const items: CommandItem[] = empty
    ? []
    : [
        {
          id: "project",
          icon: <ProjectThumbnail />,
          group: "Projects",
          label: "Website redesign",
          description: "12 open tasks · Design team",
          keywords: ["home", "project", "website", "design"],
          onSelect: () => setSelected("Opened Website redesign"),
        },
        {
          id: "docs",
          icon: <DocumentThumbnail />,
          group: "Documents",
          label: "Brand guidelines",
          description: longContent
            ? "Logo usage, color palettes, typography, voice, and everything the design team needs to keep the next launch consistent."
            : "Logos, colors & typography",
          keywords: ["help", "brand", "style guide", "logos"],
          onSelect: () => setSelected("Opened Brand guidelines"),
        },
        {
          id: "theme",
          icon: <Palette />,
          group: "Actions",
          label: "Change appearance",
          description: "Choose your workspace theme",
          keywords: ["theme", "dark", "light", "settings"],
          items: [
            {
              id: "light",
              icon: <Sun />,
              label: "Light",
              onSelect: () => setSelected("Appearance set to Light"),
            },
            {
              id: "dark",
              icon: <Moon />,
              label: "Dark",
              onSelect: () => setSelected("Appearance set to Dark"),
            },
            {
              id: "system",
              icon: <Monitor />,
              label: "System",
              onSelect: () => setSelected("Appearance follows your system"),
            },
          ],
        },
        {
          id: "save",
          icon: <FilePlus2 />,
          group: "Actions",
          label: "Create a design brief",
          description: "Start from the team template",
          onSelect: async ({ signal }) => {
            await new Promise((resolve) => setTimeout(resolve, 650));
            if (!signal.aborted) setSelected("Created a new design brief");
          },
        },
        {
          id: "retry",
          icon: <RefreshCw />,
          group: "Actions",
          label: "Sync shared files",
          description: "Get the latest team updates",
          onSelect: async ({ signal }) => {
            await new Promise((resolve) => setTimeout(resolve, 350));
            if (signal.aborted) return;
            if (simulateSyncFailure && ++attempts.current === 1)
              throw new Error("File sync unavailable");
            setSelected("Shared files are up to date");
          },
        },
        {
          id: "slow",
          icon: <Download />,
          group: "Actions",
          label: "Export project",
          description: "Package the website design assets",
          onSelect: async ({ signal }) => {
            await new Promise<void>((resolve) => setTimeout(resolve, 2000));
            if (!signal.aborted)
              setSelected("Website redesign export is ready");
          },
        },
        ...(longContent
          ? Array.from({ length: 12 }, (_, i) => ({
              id: `archive-${i}`,
              group: "Archive",
              label: `Project ${i + 1}: ${"A long project name ".repeat(5)}`,
              onSelect: () => setSelected(`Opened archive ${i + 1}`),
            }))
          : []),
      ];
  return (
    <div className="command-palette-demo flex flex-col items-center gap-5">
      {controlled && (
        <button
          type="button"
          className="rounded-lg border border-border px-4 py-2 text-sm focus-visible:ring-2 focus-visible:ring-ring"
          onClick={() => setOpen(true)}
        >
          Open commands
        </button>
      )}
      <CommandPalette
        placeholder="Search projects, docs, and actions…"
        filtersLabel="Search in"
        items={
          showcase
            ? items.filter((item) => scopes.includes(item.group ?? ""))
            : items
        }
        filters={
          showcase ? scopes.map((label) => ({ id: label, label })) : undefined
        }
        onFilterRemove={(id) =>
          setScopes((current) => current.filter((scope) => scope !== id))
        }
        footer={
          <div>
            <p>
              Need a hand?{" "}
              <button
                type="button"
                aria-expanded={helpOpen}
                className="rounded-sm text-foreground underline underline-offset-4 hover:text-foreground/80 focus-visible:outline-2 focus-visible:outline-ring"
                onClick={() => setHelpOpen((value) => !value)}
              >
                Workspace help
              </button>
            </p>
            {helpOpen && (
              <p className="mt-2 max-w-sm" role="status">
                Search “brand” to find the guidelines, “export” to package
                assets, or “theme” to change appearance. Remove a chip to
                exclude that category.
              </p>
            )}
          </div>
        }
        defaultOpen={defaultOpen}
        showTrigger={!controlled}
        open={openProp ?? (controlled ? open : undefined)}
        onOpenChange={(next) => {
          if (controlled) setOpen(next);
          onOpenChange?.(next);
        }}
      />
      {showcase && scopes.length < initialScopes.length && (
        <button
          type="button"
          className="text-xs text-muted-foreground underline focus-visible:outline-2 focus-visible:outline-ring"
          onClick={() => setScopes(initialScopes)}
        >
          Search all categories
        </button>
      )}
      <p
        className="text-center text-xs text-muted-foreground"
        data-demo-result=""
      >
        {selected}
      </p>
    </div>
  );
}

import * as React from "react";
import {
  DropZoneMembrane,
  MembraneAttachment,
  type DropZoneMembraneProps,
  type DropZoneMembraneUpload,
  type DropZoneMembraneStatus,
} from "../registry/components/drop-zone-membrane";

function wait(ms: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal.aborted) return reject(signal.reason);
    const abort = () => {
      clearTimeout(timer);
      reject(signal.reason);
    };
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", abort);
      resolve();
    }, ms);
    signal.addEventListener("abort", abort, { once: true });
  });
}

export const demoUpload: DropZoneMembraneUpload = async (
  _file,
  { signal, progress, processing },
) => {
  for (let step = 1; step <= 16; step++) {
    await wait(180, signal);
    progress(step / 16);
  }
  processing();
  await wait(800, signal);
};

export function DropZoneMembraneDemo({
  failFirst = false,
  ...props
}: DropZoneMembraneProps & { failFirst?: boolean }) {
  const attempted = React.useRef(new WeakSet<File>());
  const upload: DropZoneMembraneUpload = async (file, context) => {
    if (failFirst && !attempted.current.has(file)) {
      attempted.current.add(file);
      for (let step = 1; step <= 6; step++) {
        await wait(180, context.signal);
        context.progress(step / 10);
      }
      throw new Error("Upload failed. Try again.");
    }
    await demoUpload(file, context);
  };
  return (
    <div className="w-full max-w-[480px]">
      <DropZoneMembrane onUpload={upload} {...props} />
      <p className="mt-6 text-center text-xs text-muted-foreground">
        {props.multiple === false
          ? "One file"
          : "Up to " + (props.maxFiles ?? 2) + " files"}{" "}
        · Uploads are simulated in this example.
      </p>
    </div>
  );
}

type Example = {
  id: string;
  file: { name: string; size: number };
  status: DropZoneMembraneStatus;
  progress: number;
};
const examples: Example[] = [
  {
    id: "ready",
    file: { name: "selected-file.pdf", size: 124000 },
    status: "idle",
    progress: 0,
  },
  {
    id: "uploading",
    file: { name: "design-system.zip", size: 2400000 },
    status: "uploading",
    progress: 0.64,
  },
  {
    id: "processing",
    file: { name: "market-research.pdf", size: 780000 },
    status: "processing",
    progress: 1,
  },
  {
    id: "error",
    file: { name: "financial-model.xlsx", size: 152000 },
    status: "error",
    progress: 0.4,
  },
  {
    id: "done",
    file: { name: "uploaded-report.pdf", size: 1800000 },
    status: "done",
    progress: 1,
  },
];

export function AttachmentStatesDemo() {
  const [rows, setRows] = React.useState(examples);
  const jobs = React.useRef(new Map<string, AbortController>());
  React.useEffect(() => () => jobs.current.forEach((job) => job.abort()), []);
  const remove = (id: string) => {
    jobs.current.get(id)?.abort();
    jobs.current.delete(id);
    setRows((list) => list.filter((row) => row.id !== id));
  };
  const start = async (row: Example) => {
    jobs.current.get(row.id)?.abort();
    const job = new AbortController();
    jobs.current.set(row.id, job);
    const patch = (next: Partial<Example>) => {
      if (!job.signal.aborted)
        setRows((list) =>
          list.map((r) => (r.id === row.id ? { ...r, ...next } : r)),
        );
    };
    patch({ status: "uploading", progress: 0 });
    try {
      await demoUpload(new File([], row.file.name), {
        signal: job.signal,
        progress: (progress) => patch({ progress }),
        processing: () => patch({ status: "processing" }),
      });
      patch({ status: "done", progress: 1 });
    } catch {
      /* A removed example cancels its simulated upload. */
    } finally {
      if (jobs.current.get(row.id) === job) jobs.current.delete(row.id);
    }
  };
  return (
    <div className="w-full max-w-[384px]">
      <ul
        aria-label="Attachment states"
        className="flex list-none flex-col gap-2 p-0"
      >
        {rows.map((row) => (
          <li key={row.id}>
            <MembraneAttachment
              {...row}
              onRemove={() => remove(row.id)}
              onRetry={() => void start(row)}
            />
          </li>
        ))}
      </ul>
      <button
        className="mt-6 text-xs text-muted-foreground underline underline-offset-4"
        onClick={() => {
          jobs.current.forEach((job) => job.abort());
          jobs.current.clear();
          setRows(examples);
        }}
      >
        Reset examples
      </button>
    </div>
  );
}

