const first = {
  question: "Write a two-line tagline for our ice cream shop",
  answer: "Small batches, big flavor.\nChurned this morning, gone by tonight.",
};
const replies = [
  "Cold scoops, warm welcomes.\nChurned on Main Street every morning.",
  "Small batches, big flavor.\nMade at dawn, gone by dusk.",
  "Real cream, slow churned.\nOne scoop and you’re a regular.",
];

export function MessageEditDemo({
  disabled = false,
  initialBranches = false,
}: {
  disabled?: boolean;
  initialBranches?: boolean;
}) {
  const [branches, setBranches] = useState(() =>
    initialBranches
      ? [
          first,
          {
            question: "Make it warmer and mention Main Street",
            answer: replies[0],
          },
          {
            question: "Keep it short and focus on real ingredients",
            answer: replies[2],
          },
        ]
      : [first],
  );
  const [index, setIndex] = useState(initialBranches ? 2 : 0);
  const [streaming, setStreaming] = useState<string | null>(null);
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearInterval(timer.current), []);
  const busy = streaming !== null;
  const branch = branches[index];
  return (
    <div className="flex w-full max-w-[480px] flex-col gap-5">
      <MessageEdit
        text={branch.question}
        disabled={disabled || busy}
        onSubmit={(question) => {
          const answer = replies[branches.length % replies.length];
          const words = answer.split(/(?<=\s)/);
          setBranches((previous) => [...previous, { question, answer }]);
          setIndex(branches.length);
          setStreaming("");
          let count = 0;
          window.clearInterval(timer.current);
          timer.current = window.setInterval(() => {
            count += 1;
            setStreaming(words.slice(0, count).join(""));
            if (count >= words.length) {
              window.clearInterval(timer.current);
              setStreaming(null);
            }
          }, 70);
        }}
        versions={{
          index,
          count: branches.length,
          onIndexChange: (next) => !busy && setIndex(next),
        }}
      />
      <p
        key={index}
        className="min-h-[3.5rem] whitespace-pre-wrap text-[14px] leading-relaxed text-foreground animate-[ui-fade-in_250ms_ease-out_both] motion-reduce:animate-none"
      >
        {busy ? streaming : branch.answer}
        {busy && (
          <span
            aria-hidden="true"
            className="ml-0.5 inline-block h-[1em] w-[2px] translate-y-[2px] animate-pulse bg-foreground/70 motion-reduce:animate-none"
          />
        )}
      </p>
    </div>
  );
}

import * as React from "react";
import { NumberRoll } from "../registry/components/number-roll";
import { PrimitiveTabs } from "./primitive-tabs";

type Mode = "Try it" | "Currency" | "Compact" | "Live";
const modes: Mode[] = ["Try it", "Currency", "Compact", "Live"];

export function NumberRollDemo({
  initialMode = "Try it",
  initialValue = 1248,
}: {
  initialMode?: Mode;
  initialValue?: number;
}) {
  const [mode, setMode] = React.useState<Mode>(initialMode);
  const [value, setValue] = React.useState(
    initialMode === "Compact"
      ? 9400
      : initialMode === "Live"
        ? 12480
        : initialValue,
  );
  const [paused, setPaused] = React.useState(false);
  const panelId = React.useId();
  React.useEffect(() => {
    if (mode !== "Live" || paused) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)");
    const timer = window.setInterval(() => {
      if (!reduced.matches && document.visibilityState === "visible")
        setValue((current) => current + 1);
    }, 1600);
    return () => window.clearInterval(timer);
  }, [mode, paused]);
  const selectMode = (next: Mode) => {
    setMode(next);
    setValue(next === "Compact" ? 9400 : next === "Live" ? 12480 : 1248);
  };
  const change = (update: (current: number) => number) =>
    setValue((current) =>
      Math.max(-9999999, Math.min(9999999, update(current))),
    );
  return (
    <div className="cavemio-demo primitive-demo" data-demo="number-roll">
      <div
        className="primitive-stage"
        role="tabpanel"
        id={panelId}
        aria-labelledby={`${panelId}-${mode}`}
      >
        <div className="primitive-number" data-testid="roll-value">
          <NumberRoll
            value={value}
            locales="en-GB"
            format={
              mode === "Currency"
                ? {
                    style: "currency",
                    currency: "USD",
                    maximumFractionDigits: 0,
                  }
                : mode === "Compact"
                  ? { notation: "compact", maximumFractionDigits: 1 }
                  : { maximumFractionDigits: 0 }
            }
          />
        </div>
        <div
          className="primitive-options"
          role="group"
          aria-label="Change number"
        >
          {mode === "Live" ? (
            <>
              <span className="primitive-live">Live activity</span>
              <button
                type="button"
                aria-pressed={paused}
                onClick={() => setPaused((current) => !current)}
              >
                {paused ? "Resume" : "Pause"}
              </button>
            </>
          ) : (
            <>
              <button type="button" onClick={() => change((n) => n - 1)}>
                −1
              </button>
              <button type="button" onClick={() => change((n) => n + 1)}>
                +1
              </button>
              <button type="button" onClick={() => change((n) => n + 752)}>
                +752
              </button>
              <button type="button" onClick={() => change((n) => n * 10)}>
                ×10
              </button>
              <button
                type="button"
                onClick={() => change((n) => Math.round(n / 10))}
              >
                ÷10
              </button>
              <button
                type="button"
                onClick={() => setValue(Math.floor(Math.random() * 10000))}
              >
                Random
              </button>
            </>
          )}
        </div>
      </div>
      <PrimitiveTabs
        items={modes.map((value) => ({ value, label: value }))}
        value={mode}
        onChange={selectMode}
        label="Number Roll examples"
        panelId={panelId}
      />
    </div>
  );
}

import * as React from "react";

export function PrimitiveTabs<T extends string>({
  items,
  value,
  onChange,
  label,
  panelId,
}: {
  items: { value: T; label: string }[];
  value: T;
  onChange: (value: T) => void;
  label: string;
  panelId: string;
}) {
  const root = React.useRef<HTMLDivElement>(null);
  const [position, setPosition] = React.useState({ left: 3, width: 0 });
  React.useLayoutEffect(() => {
    const measure = () => {
      const active = root.current?.querySelector<HTMLElement>(
        '[aria-selected="true"]',
      );
      if (active)
        setPosition({ left: active.offsetLeft, width: active.offsetWidth });
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (root.current) observer.observe(root.current);
    return () => observer.disconnect();
  }, [value]);
  return (
    <div
      ref={root}
      className="primitive-tabs"
      role="tablist"
      aria-label={label}
      onKeyDown={(event) => {
        let index = items.findIndex((item) => item.value === value);
        if (event.key === "ArrowRight") index++;
        else if (event.key === "ArrowLeft") index--;
        else if (event.key === "Home") index = 0;
        else if (event.key === "End") index = items.length - 1;
        else return;
        event.preventDefault();
        const next = (index + items.length) % items.length;
        onChange(items[next].value);
        root.current
          ?.querySelectorAll<HTMLButtonElement>('[role="tab"]')
          [next]?.focus();
      }}
    >
      <span
        className="primitive-tab-highlight"
        aria-hidden="true"
        style={{
          width: position.width,
          transform: `translateX(${position.left}px)`,
          opacity: position.width ? 1 : 0,
        }}
      />
      {items.map((item) => (
        <button
          type="button"
          role="tab"
          key={item.value}
          id={`${panelId}-${item.value}`}
          aria-controls={panelId}
          aria-selected={value === item.value}
          tabIndex={value === item.value ? 0 : -1}
          onClick={() => onChange(item.value)}
        >
          {item.label}
        </button>
      ))}
    </div>
  );
}

