"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight, RotateCcw } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * RESPONSE VERSIONS: "2 / 3" between regenerated answers
 *
 *   browsing      the arrows step between versions: the answer
 *                 you leave slides out one way through a blur, the
 *                 next comes in from the other side, the height
 *                 eases between them and "2 / 3" rolls
 *   regenerating  the regenerate arrow blurs into a spinner until
 *                 the new version arrives; the count rolls up
 *
 * Wrap the current version's content.
 * ───────────────────────────────────────────────────────── */

export interface ResponseVersionsProps extends React.HTMLAttributes<HTMLDivElement> {
  count: number;
  /** Zero-based index of the version shown. */
  index: number;
  onIndexChange: (index: number) => void;
  onRegenerate?: () => void;
  regenerating?: boolean;
  /** The current version's content. */
  children: React.ReactNode;
}

type Leaving = { key: string; node: React.ReactNode; dir: number };

const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ICON = `cursor-pointer disabled:cursor-default relative flex size-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-35 ${FOCUS}`;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

/** The version you stepped away from: it leaves toward the side you came from, then removes itself. */
function LeavingPane({
  item,
  onDone,
}: {
  item: Leaving;
  onDone: (key: string) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        {
          opacity: 0,
          filter: "blur(6px)",
          transform: `translateX(${-item.dir * 24}px)`,
        },
      ],
      { duration: 260, easing: MORPH, fill: "forwards" },
    );
    animation.onfinish = () => onDone(item.key);
    return () => animation.cancel();
  }, [item, onDone]);
  return (
    <div
      ref={ref}
      inert
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0 top-0"
    >
      {item.node}
    </div>
  );
}

export function ResponseVersions({
  count,
  index,
  onIndexChange,
  onRegenerate,
  regenerating = false,
  children,
  className = "",
  ...props
}: ResponseVersionsProps) {
  const reduced = useReducedMotion();
  const boxRef = React.useRef<HTMLDivElement>(null);
  const paneRef = React.useRef<HTMLDivElement>(null);
  const latest = React.useRef<React.ReactNode>(children);
  const fromHeight = React.useRef<number | null>(null);

  // A step: what was showing (as it last rendered) leaves, and the new version comes in from the side you stepped toward.
  const [shown, setShown] = React.useState({ index, step: 0 });
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const [dir, setDir] = React.useState(0);
  if (shown.index !== index) {
    // Keep the visible height before React replaces the pane, including a
    // partially completed resize. A cached natural height jumps on reversal.
    fromHeight.current = boxRef.current?.getBoundingClientRect().height ?? null;
    const d = index > shown.index ? 1 : -1;
    setShown({ index, step: shown.step + 1 });
    setDir(reduced ? 0 : d);
    if (!reduced)
      setLeaving((l) => [
        ...l,
        // A repeated route can still have a pane leaving; each step needs its own key.
        { key: `${shown.step}`, node: latest.current, dir: d },
      ]);
    else if (leaving.length) setLeaving([]);
  }
  const done = React.useCallback(
    (key: string) => setLeaving((l) => l.filter((x) => x.key !== key)),
    [],
  );

  React.useLayoutEffect(() => {
    if (reduced) {
      setLeaving([]);
      setDir(0);
    }
  }, [reduced]);

  React.useLayoutEffect(() => {
    const from = fromHeight.current;
    fromHeight.current = null;
    if (!dir || reduced) return;
    const pane = paneRef.current;
    const box = boxRef.current;
    const enter = pane?.animate(
      [
        {
          opacity: 0,
          filter: "blur(6px)",
          transform: `translateX(${dir * 24}px)`,
        },
        { opacity: 1, filter: "blur(0px)", transform: "none" },
      ],
      { duration: 420, easing: MORPH, delay: 60, fill: "backwards" },
    );
    // The box eases from the old answer's height to the new one's.
    let resize: Animation | undefined;
    const to = box?.getBoundingClientRect().height;
    if (box && from !== null && to !== undefined && Math.abs(to - from) > 0.1) {
      box.style.overflow = "hidden";
      resize = box.animate([{ height: `${from}px` }, { height: `${to}px` }], {
        duration: 420,
        easing: MORPH,
      });
      resize.onfinish = () => {
        box.style.overflow = "";
      };
    }
    return () => {
      enter?.cancel();
      resize?.cancel();
      // Restore synchronously: an old cancellation event must not clear the
      // overflow protection of the next transition.
      if (resize && box) box.style.overflow = "";
    };
  }, [index, dir, reduced]);

  // Remember what this render showed, including streamed content, for the next step.
  React.useLayoutEffect(() => {
    latest.current = children;
  });

  return (
    <div className={className} {...props}>
      <div
        ref={boxRef}
        className={`relative ${!reduced && leaving.length ? "overflow-hidden" : ""}`}
      >
        {!reduced &&
          leaving.map((l) => (
            <LeavingPane key={l.key} item={l} onDone={done} />
          ))}
        <div key={index} ref={paneRef}>
          {children}
        </div>
      </div>

      <div className="mt-3 flex items-center gap-1">
        <button
          type="button"
          aria-label="Previous version"
          disabled={index <= 0}
          onClick={() => onIndexChange(index - 1)}
          className={ICON}
        >
          <ChevronLeft className="size-4" />
        </button>
        <span
          aria-live="polite"
          className="flex min-w-[3.25rem] justify-center gap-[0.5ch] font-mono text-[11.5px] tabular-nums text-muted-foreground"
        >
          <span className="sr-only">Version </span>
          <NumberRoll value={index + 1} duration={600} />
          <span aria-hidden="true">/</span>
          <span className="sr-only">of</span>
          <NumberRoll value={count} duration={600} />
        </span>
        <button
          type="button"
          aria-label="Next version"
          disabled={index >= count - 1}
          onClick={() => onIndexChange(index + 1)}
          className={ICON}
        >
          <ChevronRight className="size-4" />
        </button>
        {onRegenerate && (
          <button
            type="button"
            aria-label={regenerating ? "Regenerating" : "Regenerate"}
            disabled={regenerating}
            onClick={onRegenerate}
            className={`cursor-pointer disabled:cursor-default ${ICON} ml-1`}
          >
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(!regenerating, reduced)}
            >
              <RotateCcw className="size-3.5" />
            </span>
            <span
              aria-hidden="true"
              className="absolute inset-0 flex items-center justify-center"
              style={swap(regenerating, reduced)}
            >
              <span
                className={`size-3.5 rounded-full border-[1.5px] border-border border-t-foreground/70 motion-reduce:animate-none ${regenerating ? "animate-spin" : ""}`}
              />
            </span>
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { Field, useFieldIds } from "./field";
import {
  PillSelect,
  type PillOption,
  type PillSelectProps,
} from "./pill-select";

/* ─────────────────────────────────────────────────────────
 * SELECT: a choice from a list, never the browser's dropdown
 *
 *   open     the pill grows into its list (size and corners ease)
 *            from the edge it lines up with; upward when there's
 *            no room below; long lists scroll
 *   pick     the list folds back into the pill and the label
 *            morphs to the choice, which carries a drawn check
 *   keys     arrows glide a highlight, typing finds an option,
 *            Enter picks, Escape folds it back
 *
 * The list lives in a portal, so no toolbar, card or scroller
 * clips it. Labelled and hinted like every other field.
 * ───────────────────────────────────────────────────────── */

export type SelectOption = PillOption;

export interface SelectProps extends Omit<
  PillSelectProps,
  "label" | "value" | "onValueChange"
> {
  /** Shown above; also the accessible name. */
  label: string;
  /** Hide the label visually (it stays the accessible name). */
  hideLabel?: boolean;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  value?: string | null;
  defaultValue?: string | null;
  onValueChange?: (value: string) => void;
  id?: string;
}

export function Select({
  label,
  hideLabel,
  hint,
  error,
  value,
  defaultValue = null,
  onValueChange,
  id,
  className = "",
  block = true,
  size = "md",
  ...props
}: SelectProps) {
  const ids = useFieldIds(id);
  const [own, setOwn] = React.useState<string | null>(defaultValue);
  const current = value !== undefined ? value : own;
  return (
    <Field
      id={ids.id}
      label={hideLabel ? undefined : label}
      hint={hint}
      error={error}
      className={className}
    >
      <PillSelect
        {...props}
        id={ids.id}
        aria-describedby={error ? ids.error : hint ? ids.hint : undefined}
        aria-invalid={error ? true : undefined}
        block={block}
        size={size}
        label={label}
        value={current}
        onValueChange={(v) => {
          if (value === undefined) setOwn(v);
          onValueChange?.(v);
        }}
      />
    </Field>
  );
}

export default Select;

"use client";

import {
  useEffect,
  useEffectEvent,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { lifecycleEase, useLifecycleReducedMotion } from "./lifecycle-motion";

export interface TimelineStep {
  id: string;
  title: string;
  description: ReactNode;
}

export interface StepTimelineProps {
  /** Nonempty steps with unique, stable IDs. */
  steps: readonly TimelineStep[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Opt in to timed progression. */
  autoPlay?: boolean;
  duration?: number;
  disabled?: boolean;
  ariaLabel?: string;
  className?: string;
  style?: CSSProperties;
}

/** An independently usable, expanding step selector with optional timed progress. */
export function StepTimeline({
  steps,
  value,
  defaultValue,
  onValueChange,
  autoPlay = false,
  duration = 5500,
  disabled = false,
  ariaLabel = "Timeline",
  className = "",
  style,
}: StepTimelineProps) {
  const [internalValue, setInternalValue] = useState(
    defaultValue ?? steps[0]?.id,
  );
  const selected =
    steps.find((step) => step.id === (value ?? internalValue))?.id ??
    steps[0]?.id;
  const [restart, setRestart] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [visible, setVisible] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);
  const reduced = useLifecycleReducedMotion();
  const root = useRef<HTMLDivElement>(null);
  const fill = useRef<HTMLSpanElement>(null);
  const animation = useRef<Animation | null>(null);
  const cycling = autoPlay && !disabled && !reduced && steps.length > 1;
  const running =
    cycling && !paused && !hovered && !focused && visible && pageVisible;
  const select = (id: string) => {
    if (disabled) return;
    setInternalValue(id);
    setRestart((n) => n + 1);
    if (id !== selected) onValueChange?.(id);
  };
  const advance = useEffectEvent(() => {
    const next =
      steps[
        (steps.findIndex((step) => step.id === selected) + 1) % steps.length
      ];
    if (next) select(next.id);
  });

  useEffect(() => {
    const node = root.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => setVisible(entry.isIntersecting),
      { threshold: 0.25 },
    );
    observer.observe(node);
    const update = () => setPageVisible(!document.hidden);
    update();
    document.addEventListener("visibilitychange", update);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", update);
    };
  }, []);

  useEffect(() => {
    if (!cycling || !fill.current) return;
    const playback = fill.current.animate(
      [{ transform: "scaleY(0)" }, { transform: "scaleY(1)" }],
      { duration: Math.max(1000, duration), fill: "both", easing: "linear" },
    );
    playback.pause();
    playback.onfinish = () => advance();
    animation.current = playback;
    return () => {
      playback.cancel();
      animation.current = null;
    };
  }, [selected, restart, cycling, duration]);

  useEffect(() => {
    if (running) animation.current?.play();
    else animation.current?.pause();
  }, [running, selected, restart, cycling, duration]);

  if (!steps.length) return null;
  return (
    <div
      ref={root}
      className={`w-full text-foreground ${className}`}
      style={style}
    >
      <ol
        aria-label={ariaLabel}
        className="m-0 list-none p-0"
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocusCapture={() => setFocused(true)}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget))
            setFocused(false);
        }}
      >
        {steps.map((step, index) => {
          const active = selected === step.id;
          return (
            <li key={step.id}>
              <button
                type="button"
                aria-pressed={active}
                aria-expanded={active}
                aria-label={step.title}
                disabled={disabled}
                onClick={() => select(step.id)}
                onKeyDown={(event) => {
                  const direction =
                    event.key === "ArrowDown" || event.key === "ArrowRight"
                      ? 1
                      : event.key === "ArrowUp" || event.key === "ArrowLeft"
                        ? -1
                        : 0;
                  const next =
                    event.key === "Home"
                      ? 0
                      : event.key === "End"
                        ? steps.length - 1
                        : direction
                          ? (index + direction + steps.length) % steps.length
                          : null;
                  if (next === null) return;
                  event.preventDefault();
                  select(steps[next].id);
                  root.current
                    ?.querySelectorAll<HTMLButtonElement>("ol button")
                    [next]?.focus();
                }}
                className="group relative block w-full cursor-pointer rounded-sm py-4 pl-7 text-left outline-offset-4 focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50"
              >
                <span
                  aria-hidden="true"
                  className="absolute inset-y-1 left-0 w-0.5 overflow-hidden rounded-full bg-border"
                >
                  {active && (
                    <span
                      key={`${step.id}-${restart}`}
                      ref={fill}
                      className="absolute inset-0 origin-top bg-foreground"
                    />
                  )}
                </span>
                <span
                  className={`block transition-colors duration-300 motion-reduce:transition-none ${active ? "text-foreground" : "text-muted-foreground group-hover:text-foreground"}`}
                >
                  <span className="block text-[22px] leading-[1.25] font-normal tracking-[-0.02em] [font-family:var(--timeline-display-font,inherit)] md:text-[24px]">
                    {step.title}
                  </span>
                  <span
                    aria-hidden={!active}
                    inert={!active}
                    className="grid motion-reduce:transition-none"
                    style={{
                      gridTemplateRows: active ? "1fr" : "0fr",
                      transition: reduced
                        ? "none"
                        : `grid-template-rows 500ms ${lifecycleEase}`,
                    }}
                  >
                    <span className="min-h-0 overflow-hidden">
                      <span className="block max-w-96 pt-2 text-[16.5px] leading-[1.55] tracking-[-0.012em] text-pretty text-muted-foreground">
                        {step.description}
                      </span>
                    </span>
                  </span>
                </span>
              </button>
            </li>
          );
        })}
      </ol>
      {autoPlay && !reduced && (
        <button
          type="button"
          disabled={disabled}
          onClick={() => setPaused((current) => !current)}
          className="mt-4 min-h-11 cursor-pointer rounded-full border border-border px-4 text-xs text-muted-foreground outline-offset-4 focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50"
          aria-label={paused ? "Play timeline" : "Pause timeline"}
        >
          {paused ? "Play" : "Pause"}
        </button>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

